#!/usr/bin/env bash
# Generate terraform/terraform.tfvars.json from config/config.yaml.
# Non-secret values only; the VM admin password is generated by Terraform.
set -euo pipefail

source "$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)/lib.sh"

require_config
require_cmd yq
require_cmd python3

OUT="${PROJECT_DIR}/terraform/terraform.tfvars.json"
TMP_JSON="$(mktemp)"
trap 'rm -f "${TMP_JSON}"' EXIT
yq -o=json '.' "${CONFIG_FILE}" > "${TMP_JSON}"

python3 - "${TMP_JSON}" "${OUT}" <<'PY'
import json
import sys

config = json.load(open(sys.argv[1], encoding="utf-8"))
output = sys.argv[2]


def clean(value, default=""):
    if value is None or value == "null" or value == "<INPUT>":
        return default
    return value


def section(parent, key):
    value = parent.get(key) if isinstance(parent, dict) else None
    return value if isinstance(value, dict) else {}


azure = section(config, "azure")
network = section(azure, "network")
aks = section(azure, "aks")
dns = section(azure, "private_dns")
kv = section(azure, "keyvault")
vm = section(azure, "vm")
agw = section(azure, "agw")
app = section(config, "application")
kong = section(config, "kong")
backends = config.get("backends") or []

vm_names = [b.get("name", "") for b in backends]
if len(backends) < 2:
    raise SystemExit("config.backends must define two VMs")

data = {
    "subscription_id": clean(azure.get("subscription_id")),
    "resource_group_name": clean(section(azure, "resource_group").get("name"), "rg-pairs-monitor-dev"),
    "create_resource_group": True,
    "location": clean(azure.get("location"), "eastus"),
    "environment": clean(azure.get("environment"), "dev"),
    "tags": {},

    "vnet_name": clean(network.get("vnet_name"), "vnet-pairs-monitor-dev"),
    "vnet_cidr": clean(network.get("vnet_cidr"), "10.20.0.0/16"),
    "aks_subnet_cidr": clean(network.get("aks_subnet_cidr"), "10.20.1.0/24"),
    "vm_subnet_cidr": clean(network.get("vm_subnet_cidr"), "10.20.2.0/24"),
    "agw_subnet_cidr": clean(network.get("agw_subnet_cidr"), "10.20.4.0/24"),
    "bastion_subnet_cidr": clean(section(azure, "bastion").get("subnet_cidr"), "10.20.3.0/24"),
    "pod_cidr": clean(network.get("pod_cidr"), "10.244.0.0/16"),
    "service_cidr": clean(network.get("service_cidr"), "10.96.0.0/16"),
    "dns_service_ip": clean(network.get("dns_service_ip"), "10.96.0.10"),
    "enable_nat_gateway": bool(network.get("nat_gateway", True)),

    "frontend_hostname": clean(app.get("public_hostname"), "fe.internal.example.com"),
    "backend_hostname": clean(app.get("backend_hostname"), "be.internal.example.com"),
    "internal_dns_zone": clean(dns.get("zone_name"), "internal.example.com"),
    "backend_dns_record": clean(dns.get("record_name"), "be"),
    "dns_ttl": int(dns.get("ttl", 300)),
    "kong_internal_lb_ip": clean(kong.get("internal_lb_ip"), "10.20.1.250"),

    "vm1_ip": clean(backends[0].get("private_ip"), "10.20.2.51"),
    "vm2_ip": clean(backends[1].get("private_ip"), "10.20.2.52"),
    "admin_username": clean(vm.get("admin_username"), "azureuser"),
    "vm_size": clean(vm.get("size"), "Standard_B2s"),
    "vm_image_publisher": clean(vm.get("image_publisher"), "Canonical"),
    "vm_image_offer": clean(vm.get("image_offer"), "ubuntu-24_04-lts"),
    "vm_image_sku": clean(vm.get("image_sku"), "server"),
    "vm_image_version": clean(vm.get("image_version"), "latest"),
    "os_disk_type": clean(vm.get("os_disk_type"), "Standard_LRS"),
    "os_disk_size_gb": int(vm.get("os_disk_size_gb", 30)),

    "aks_name": clean(aks.get("name"), "aks-pairs-monitor-dev"),
    "kubernetes_version": clean(aks.get("kubernetes_version"), "1.34"),
    "node_vm_size": clean(aks.get("node_vm_size"), "Standard_B4ms"),
    "node_min_count": int(aks.get("node_min_count", 1)),
    "node_max_count": int(aks.get("node_max_count", 2)),
    "aks_authorized_ip_ranges": aks.get("authorized_ip_ranges") or [],
    "aks_private_cluster": bool(aks.get("private_cluster", False)),

    "key_vault_name": clean(kv.get("name"), ""),
    "key_vault_allowed_ip_ranges": kv.get("allowed_ip_ranges") or [],
    "key_vault_purge_protection": True,

    "enable_application_gateway": bool(agw.get("enabled", False)),
    "agw_name": clean(agw.get("name"), "agw-pairs-monitor-dev"),
    "agw_public_ip_name": clean(agw.get("public_ip_name"), "pip-agw-pairs-monitor-dev"),
    "agw_capacity": int(agw.get("capacity", 1)),
    "agw_certificate_secret_id": clean(agw.get("certificate_secret_id"), ""),
    "root_ca_cert_path": clean(agw.get("trusted_root_ca_path"), "../pki/root-ca.crt"),

    "enable_bastion": bool(section(azure, "bastion").get("enabled", True)),
    "bastion_name": clean(section(azure, "bastion").get("name"), "bas-pairs-monitor-dev"),
    "bastion_public_ip_name": clean(section(azure, "bastion").get("public_ip_name"), "pip-bas-pairs-monitor-dev"),
}

if not data["subscription_id"]:
    raise SystemExit("azure.subscription_id is required in config/config.yaml")

with open(output, "w", encoding="utf-8") as handle:
    json.dump(data, handle, indent=2)
    handle.write("\n")

print(f"generated {output}")
PY
